n=28
g=[[0]*n for _ in range(n)]
# lattice fills; separators are the 8-valued lines
cells={(0,2):3,(1,0):2,(1,1):2,(1,2):6,(1,3):2,(1,4):2,(2,0):2,(2,2):3,(3,0):2,(3,2):3,(4,2):3}
for r in range(5):
    for c in range(5):
        if (r,c) in cells:
            for i in range(r*5,r*5+4):
                for j in range(c*5,c*5+4): g[i][j]=cells[r,c]
for i in range(n):
    if i%5==4: g[i]=[8]*n
    else:
        for j in range(4, n, 5): g[i][j]=8
import json
print(json.dumps(g,separators=(',',':')))
